//! FEA acceptance obligations (the register, kept in the capability ledger
//! docs/simulation/ledger.json) and the scanner for witness tags declared at
//! tests. Register integrity never certifies that a witness passed; the evidence report runs them.
#[cfg(feature = "docs-export")]
pub mod export;
pub mod requirement;
pub mod witness;
/// The register, generated by build.rs from docs/simulation/ledger.json.
mod requirements {
    include!(concat!(env!("OUT_DIR"), "/requirements.rs"));
}

pub fn requirements() -> impl Iterator<Item = &'static requirement::Requirement> {
    requirements::ALL.iter().flat_map(|domain| domain.iter())
}

/// Ids of the ledger's reference checks; a `; check:` witness field must name one.
pub fn checks() -> impl Iterator<Item = &'static str> {
    requirements::CHECKS.iter().copied()
}

/// Deterministic tab-separated discovery inventory. No row represents a passed gate.
/// Tabs, newlines, carriage returns and backslashes inside fields are escaped.
/// Witnesses are declared at tests (see `witness`) and appear in the evidence report.
pub fn write_inventory(mut output: impl std::io::Write) -> std::io::Result<()> {
    fn row(out: &mut impl std::io::Write, fields: &[&str]) -> std::io::Result<()> {
        for (index, field) in fields.iter().enumerate() {
            if index != 0 {
                out.write_all(b"\t")?;
            }
            for character in field.chars() {
                match character {
                    '\\' => out.write_all(b"\\\\")?,
                    '\t' => out.write_all(b"\\t")?,
                    '\n' => out.write_all(b"\\n")?,
                    '\r' => out.write_all(b"\\r")?,
                    _ => {
                        let mut bytes = [0; 4];
                        out.write_all(character.encode_utf8(&mut bytes).as_bytes())?;
                    }
                }
            }
        }
        out.write_all(b"\n")
    }
    row(&mut output, &["inventory", "1", "discovery_only"])?;
    for requirement in requirements() {
        row(
            &mut output,
            &[
                "requirement",
                requirement.id,
                requirement.title,
                requirement.acceptance,
                &format!("{:?}", requirement.stages),
            ],
        )?;
        for owner in requirement.owners {
            row(&mut output, &["owner", requirement.id, owner])?;
        }
        for dependency in requirement.dependencies {
            row(&mut output, &["dependency", requirement.id, dependency])?;
        }
        for obligation in requirement.obligations {
            row(
                &mut output,
                &[
                    "obligation",
                    requirement.id,
                    obligation.id,
                    obligation.criterion,
                    &format!("{:?}", obligation.evidence_kind),
                ],
            )?;
            for envelope in obligation.required_envelopes {
                row(
                    &mut output,
                    &[
                        "required",
                        requirement.id,
                        obligation.id,
                        &format!("{:?}", envelope.formulation),
                        &format!("{:?}", envelope.mesh),
                        &format!("{:?}", envelope.execution),
                    ],
                )?;
            }
        }
    }
    Ok(())
}
